using System;using System.Reflection;using System.Drawing;using System.Windows.Forms;
class CheckButtons{static void C(bool b,string m){if(!b)throw new Exception(m);}static void Walk(Control c){c.PerformLayout();foreach(Control x in c.Controls){if(x is Button){Control a=x;while(a.Parent!=null){C(a.Left>=0&&a.Top>=0&&a.Right<=a.Parent.ClientSize.Width&&a.Bottom<=a.Parent.ClientSize.Height,"Clipped: "+x.Text);a=a.Parent;}}Walk(x);}}[STAThread]static void Main(){Application.EnableVisualStyles();var f=BindingFlags.Instance|BindingFlags.NonPublic;using(var a=new BurnModern()){var t=typeof(BurnModern);var combo=(ComboBox)t.GetField("chips",f).GetValue(a);C(combo.Items.Count==12,"Profile count");foreach(bool connected in new[]{false,true})foreach(bool busy in new[]{false,true}){t.GetField("connectedPort",f).SetValue(a,connected?"TEST":null);t.GetField("hardwareBusy",f).SetValue(a,busy);for(int p=0;p<12;p++){combo.SelectedIndex=p;t.GetMethod("UpdateChipControls",f).Invoke(a,null);foreach(string n in new[]{"readControl","verifyControl","blankControl","disconnectControl","eraseControl","programControl"}){bool expected=connected&&!busy;if(n=="eraseControl")expected &= BurnModern.CanErase(p);if(n=="programControl")expected &= BurnModern.CanProgram(p);C(((Button)t.GetField(n,f).GetValue(a)).Enabled==expected,"Interlock: "+n+" profile "+p);}}}foreach(var size in new[]{new Size(1040,700),new Size(1120,790)}){a.Size=size;Walk(a);}C(!a.DisconnectSession(),"Busy disconnect accepted");t.GetField("hardwareBusy",f).SetValue(a,false);C(a.DisconnectSession(),"Disconnect failed");}foreach(var pair in new[]{new[]{3840,0,51},new[]{130816,1,53},new[]{261888,1,74}}){var packet=BurnModern.ReadCommand(pair[0],pair[1]==1,(char)pair[2]);int sum=0;for(int i=0;i<packet.Length-1;i++)sum+=packet[i];C(packet[packet.Length-1]==(byte)sum,"Read checksum");}var bytes=new byte[262144];for(int addr=0;addr<bytes.Length;addr+=256){var p=BurnModern.FordPacket('W',addr,bytes,addr,256);C(p.Length==263&&p[0]=='J'&&p[2]==0,"F3 packet");}Console.WriteLine("PASS: all buttons fit at both window sizes; 288 profile/state interlock checks; disconnect guard; added read packets and all F3 write addresses. No hardware commands.");}}
